#!/usr/bin/env bash
# Circom / Groth16 checks for the redemption circuit.
#
#   compile -> valid vectors TV-* (witness correct, public outputs equal
#   testdata/kat/canonical_fixture.json) -> attack vectors NT-* (each must be
#   rejected by a circuit constraint) -> isolated Schnorr vectors -> Groth16
#   setup -> prove/verify TV-* -> tampered public signals must not verify.
#
# Vectors are generated by circom/scripts/build_canonical_fixture.js.
#
# The Powers-of-Tau file is a LOCAL, single-contributor development ceremony
# with fixed entropy, made only so the test is reproducible. It is not a
# production trusted setup.
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
LOG="${ZKEP_RESULTS:-$REPO/results}/logs/circom.log"
# shellcheck source=lib/report.sh
. "$REPO/scripts/lib/report.sh"
: >"$LOG"

CIRCOM_DIR="$REPO/circom"
TMP="${TMPDIR:-/tmp}/zkep-circom"
VEC="$CIRCOM_DIR/inputs/eprescription/canonical"
FIXTURE="$REPO/testdata/kat/canonical_fixture.json"
CIRCUIT=redemption
PTAU_POWER=15
SNARKJS="${SNARKJS:-snarkjs}"
WASM="$TMP/${CIRCUIT}_js/$CIRCUIT.wasm"
GEN="$TMP/${CIRCUIT}_js/generate_witness.js"
: >"$RESULTS/circom_negative.tsv"

rm -rf "$TMP"
mkdir -p "$TMP"

# --- compile -----------------------------------------------------------------
quiet circom "$CIRCOM_DIR/circuits/$CIRCUIT.circom" --r1cs --wasm --sym -o "$TMP" \
    || fail "compile circuits/$CIRCUIT.circom" "compiler error"
"$SNARKJS" r1cs info "$TMP/$CIRCUIT.r1cs" >"$TMP/r1cs_info.txt" 2>&1
cat "$TMP/r1cs_info.txt" >>"$LOG"
CONSTRAINTS="$(sed -n 's/.*# of Constraints: *\([0-9]*\).*/\1/p' "$TMP/r1cs_info.txt")"
record circom_constraints "$CONSTRAINTS"
ok "compile circuits/$CIRCUIT.circom" "$CONSTRAINTS R1CS constraints"

# --- valid vectors -----------------------------------------------------------
check_outputs() { # $1 = vector id, $2 = witness json
    node -e '
const fx = require(process.argv[1]);
const w = require(process.argv[2]);
const e = fx.expected_public_outputs[process.argv[3]];
const hex = (x) => "0x" + BigInt(x).toString(16).padStart(64, "0");
// witness layout: [1, commitment_out, nullifier_out, current_date, root, ...]
const got = { commitment: hex(w[1]), nullifier: hex(w[2]), current_date: BigInt(w[3]).toString(), registry_root: hex(w[4]) };
let ok = true;
for (const k of ["commitment", "nullifier", "current_date", "registry_root"])
  if (got[k] !== e[k]) { ok = false; console.log(`${process.argv[3]} MISMATCH ${k}: got ${got[k]} expected ${e[k]}`); }
console.log(`${process.argv[3]} C=${got.commitment} N=${got.nullifier}`);
process.exit(ok ? 0 : 1);
' "$FIXTURE" "$2" "$1" >>"$LOG" 2>&1
}

n=0
for input in "$VEC"/TV-*.json; do
    id="$(basename "$input" .json)"
    quiet node "$GEN" "$WASM" "$input" "$TMP/$id.wtns" || fail "valid vector $id" "witness generation failed"
    "$SNARKJS" wtns check "$TMP/$CIRCUIT.r1cs" "$TMP/$id.wtns" >"$TMP/wtns_check.log" 2>&1 || true
    cat "$TMP/wtns_check.log" >>"$LOG"
    grep -q "WITNESS IS CORRECT" "$TMP/wtns_check.log" || fail "valid vector $id" "witness does not satisfy the R1CS"
    quiet "$SNARKJS" wtns export json "$TMP/$id.wtns" "$TMP/$id.wtns.json"
    check_outputs "$id" "$TMP/$id.wtns.json" || fail "valid vector $id" "public outputs differ from the fixture"
    n=$((n + 1))
done
record circom_valid "$n"
ok "valid vectors TV-001..$(printf '%03d' "$n")" "$n/$n witnesses correct, outputs = fixture"

# --- attack vectors ----------------------------------------------------------
n=0; total=0
for input in "$VEC"/NT-*.json; do
    id="$(basename "$input" .json)"
    total=$((total + 1))
    if node "$GEN" "$WASM" "$input" "$TMP/negative.wtns" >"$TMP/error.log" 2>&1; then
        cat "$TMP/error.log" >>"$LOG"
        fail "attack vector $id" "unexpectedly ACCEPTED"
    fi
    { echo "--- $id"; cat "$TMP/error.log"; } >>"$LOG"
    grep -q "Assert Failed" "$TMP/error.log" || fail "attack vector $id" "tool or input error, not a constraint"
    where="$(grep -m1 -oE 'Error in template [A-Za-z0-9_]+ line: [0-9]+' "$TMP/error.log" \
        | sed -E 's/Error in template ([A-Za-z0-9]+)_[0-9]+ line: ([0-9]+)/\1\t\2/')"
    printf '%s\t%s\n' "$id" "$where" >>"$RESULTS/circom_negative.tsv"
    n=$((n + 1))
done
record circom_attacks "$n/$total"
ok "attack vectors NT-001..$(printf '%03d' "$total")" "$n/$total rejected by a constraint"

# --- isolated Schnorr vectors ------------------------------------------------
quiet circom "$CIRCOM_DIR/circuits/kat/schnorr_unit.circom" --wasm -o "$TMP"
n=0; total=0
for input in "$CIRCOM_DIR"/inputs/unit/schnorr_canonical/SIG-*.json; do
    id="$(basename "$input" .json)"
    total=$((total + 1))
    if node "$TMP/schnorr_unit_js/generate_witness.js" "$TMP/schnorr_unit_js/schnorr_unit.wasm" \
        "$input" "$TMP/sig.wtns" >"$TMP/error.log" 2>&1; then
        [ "$id" = "SIG-OK" ] || fail "Schnorr vector $id" "unexpectedly ACCEPTED"
    else
        { echo "--- $id"; cat "$TMP/error.log"; } >>"$LOG"
        [ "$id" != "SIG-OK" ] || fail "Schnorr vector $id" "valid signature rejected"
        grep -q "Assert Failed" "$TMP/error.log" || fail "Schnorr vector $id" "tool or input error"
    fi
    n=$((n + 1))
done
record circom_schnorr "$n/$total"
ok "Schnorr vectors (1 valid, $((total - 1)) invalid)" "$n/$total as expected"

# --- Groth16 setup -----------------------------------------------------------
(
    cd "$TMP"
    if [ -n "${ZKEP_PTAU:-}" ]; then
        cp "$ZKEP_PTAU" pot_final.ptau
    else
        quiet "$SNARKJS" powersoftau new bn128 "$PTAU_POWER" pot_0000.ptau
        quiet "$SNARKJS" powersoftau contribute pot_0000.ptau pot_0001.ptau --name="zkep-dev" -e="zkep-dev-entropy"
        quiet "$SNARKJS" powersoftau prepare phase2 pot_0001.ptau pot_final.ptau
    fi
    quiet "$SNARKJS" groth16 setup "$CIRCUIT.r1cs" pot_final.ptau circuit_0000.zkey
    quiet "$SNARKJS" zkey contribute circuit_0000.zkey circuit_final.zkey --name="zkep-dev" -e="zkep-dev-zkey-entropy"
    quiet "$SNARKJS" zkey export verificationkey circuit_final.zkey verification_key.json
) || fail "Groth16 setup" "snarkjs error"
ok "Groth16 setup (local dev ceremony, not production)" "done"

# --- prove / verify ----------------------------------------------------------
n=0
for input in "$VEC"/TV-*.json; do
    id="$(basename "$input" .json)"
    quiet "$SNARKJS" groth16 prove "$TMP/circuit_final.zkey" "$TMP/$id.wtns" \
        "$TMP/$id.proof.json" "$TMP/$id.public.json" || fail "Groth16 proof $id" "prover error"
    "$SNARKJS" groth16 verify "$TMP/verification_key.json" "$TMP/$id.public.json" "$TMP/$id.proof.json" \
        >"$TMP/verify.log" 2>&1 || true
    cat "$TMP/verify.log" >>"$LOG"
    grep -q "OK!" "$TMP/verify.log" || fail "Groth16 proof $id" "proof does not verify"
    n=$((n + 1))
done
record circom_proofs "$n/$n"
ok "Groth16 prove + verify TV-001..$(printf '%03d' "$n")" "$n/$n proofs verified"

# --- tampered public signals -------------------------------------------------
id=TV-001
for idx in 0 1 2 3; do
    node -e '
const fs = require("fs");
const p = JSON.parse(fs.readFileSync(process.argv[1]));
const i = Number(process.argv[2]);
p[i] = (BigInt(p[i]) + 1n).toString();
fs.writeFileSync(process.argv[3], JSON.stringify(p));
' "$TMP/$id.public.json" "$idx" "$TMP/tampered.public.json"
    if "$SNARKJS" groth16 verify "$TMP/verification_key.json" \
        "$TMP/tampered.public.json" "$TMP/$id.proof.json" >"$TMP/verify.log" 2>&1 \
        && grep -q "OK!" "$TMP/verify.log"; then
        fail "tampered public signal [$idx]" "VERIFIED"
    fi
done
record circom_tampered "4/4"
ok "tampered public signals (C, N, date, root)" "4/4 rejected"
